// @homepageURL  https://github.com/cycledm/userscripts/tree/main/steam-store-region
// @supportURL   https://github.com/cycledm/userscripts/issues
// @match        https://store.steampowered.com/*
// @run-at       document-end
// @noframes
// @grant        GM_getValue
// @grant        GM_setValue
// ==/UserScript==

