(() => {
    'use strict';

    const OPTIONS = [['cn', '🇨🇳 国区', '🇨🇳 CN'], ['hk', '🇭🇰 港区', '🇭🇰 HK'],
        ['jp', '🇯🇵 日区', '🇯🇵 JP'], ['us', '🇺🇸 美区', '🇺🇸 US'],
        ['off', '🌐 默认', '🌐 Default']];
    const SETTING = 'steam-store-region';
    const COLLAPSED_SETTING = 'steam-store-region-collapsed';
    const LOOP_KEY = 'cycledm-steam-region-last-navigation';
    // Generated by src/build-styles.py from Tailwind CSS 3.4.17 (MIT).
    // tailwind:start
    const STYLES = ":host{all:initial}.visible{visibility:visible}.fixed{position:fixed}.bottom-4{bottom:1rem}.right-4{right:1rem}.z-\\[2147483647\\]{z-index:2147483647}.m-0{margin:0}.flex{display:flex}.grid{display:grid}.w-max{width:-moz-max-content;width:max-content}.min-w-0{min-width:0}.max-w-\\[calc\\(100vw-2rem\\)\\]{max-width:calc(100vw - 2rem)}.max-w-\\[calc\\(100vw-6rem\\)\\]{max-width:calc(100vw - 6rem)}.cursor-pointer{cursor:pointer}.grid-cols-\\[1fr\\]{grid-template-columns:1fr}.flex-wrap{flex-wrap:wrap}.items-center{align-items:center}.gap-1{gap:.25rem}.overflow-hidden{overflow:hidden}.rounded-lg{border-radius:.5rem}.rounded-xl{border-radius:.75rem}.border{border-width:1px}.border-0{border-width:0}.border-solid{border-style:solid}.border-slate-600{--tw-border-opacity:1;border-color:rgb(71 85 105/var(--tw-border-opacity,1))}.bg-slate-700{--tw-bg-opacity:1;background-color:rgb(51 65 85/var(--tw-bg-opacity,1))}.bg-slate-900{--tw-bg-opacity:1;background-color:rgb(15 23 42/var(--tw-bg-opacity,1))}.p-1{padding:.25rem}.p-2{padding:.5rem}.px-2{padding-left:.5rem;padding-right:.5rem}.px-3{padding-left:.75rem;padding-right:.75rem}.py-2{padding-top:.5rem;padding-bottom:.5rem}.font-sans{font-family:ui-sans-serif,system-ui,sans-serif,Apple Color Emoji,Segoe UI Emoji,Segoe UI Symbol,Noto Color Emoji}.text-sm{font-size:.875rem;line-height:1.25rem}.text-xs{font-size:.75rem;line-height:1rem}.font-medium{font-weight:500}.leading-5{line-height:1.25rem}.text-slate-100{--tw-text-opacity:1;color:rgb(241 245 249/var(--tw-text-opacity,1))}.text-slate-300{--tw-text-opacity:1;color:rgb(203 213 225/var(--tw-text-opacity,1))}.text-white{--tw-text-opacity:1;color:rgb(255 255 255/var(--tw-text-opacity,1))}.opacity-100{opacity:1}.shadow{--tw-shadow:0 1px 3px 0 rgba(0,0,0,.1),0 1px 2px -1px rgba(0,0,0,.1);--tw-shadow-colored:0 1px 3px 0 var(--tw-shadow-color),0 1px 2px -1px var(--tw-shadow-color)}.shadow,.shadow-lg{box-shadow:var(--tw-ring-offset-shadow,0 0 #0000),var(--tw-ring-shadow,0 0 #0000),var(--tw-shadow)}.shadow-lg{--tw-shadow:0 10px 15px -3px rgba(0,0,0,.1),0 4px 6px -4px rgba(0,0,0,.1);--tw-shadow-colored:0 10px 15px -3px var(--tw-shadow-color),0 4px 6px -4px var(--tw-shadow-color)}.filter{filter:var(--tw-blur) var(--tw-brightness) var(--tw-contrast) var(--tw-grayscale) var(--tw-hue-rotate) var(--tw-invert) var(--tw-saturate) var(--tw-sepia) var(--tw-drop-shadow)}.transition-\\[grid-template-columns\\2c opacity\\]{transition-property:grid-template-columns,opacity;transition-timing-function:cubic-bezier(.4,0,.2,1);transition-duration:.15s}.duration-200{transition-duration:.2s}.ease-in-out{transition-timing-function:cubic-bezier(.4,0,.2,1)}.hover\\:bg-slate-600:hover{--tw-bg-opacity:1;background-color:rgb(71 85 105/var(--tw-bg-opacity,1))}.focus-visible\\:outline:focus-visible{outline-style:solid}.focus-visible\\:outline-2:focus-visible{outline-width:2px}.focus-visible\\:outline-offset-2:focus-visible{outline-offset:2px}.focus-visible\\:outline-sky-300:focus-visible{outline-color:#7dd3fc}.disabled\\:cursor-default:disabled{cursor:default}.disabled\\:opacity-50:disabled{opacity:.5}.aria-pressed\\:bg-sky-700[aria-pressed=true]{--tw-bg-opacity:1;background-color:rgb(3 105 161/var(--tw-bg-opacity,1))}.data-\\[collapsed\\=true\\]\\:grid-cols-\\[0fr\\][data-collapsed=true]{grid-template-columns:0fr}.data-\\[collapsed\\=true\\]\\:opacity-0[data-collapsed=true]{opacity:0}@media (prefers-reduced-motion:reduce){.motion-reduce\\:transition-none{transition-property:none}}";
    // tailwind:end

    if (window.top !== window.self || location.origin !== 'https://store.steampowered.com') return;
    const allowed = /^\/(?:$|(?:app|bundle|sub|search|category|genre|tags|specials|sale|charts|publisher|developer|franchise|curators?|wishlist|points|explore|steamdeck)(?:\/|$))/;
    if (!allowed.test(location.pathname) || /^\/search\/results(?:\/|$)/i.test(location.pathname)) return;

    const chinese = /^zh\b/i.test(document.documentElement.lang || navigator.language);
    let region = 'cn';
    try {
        const saved = GM_getValue(SETTING, 'cn');
        if (OPTIONS.some(([value]) => value === saved)) region = saved;
    } catch (_) { /* Retain the default when settings cannot be read. */ }

    function loginState() {
        // Account UI takes priority over a possibly stale signed-out marker.
        if (document.querySelector('#account_pulldown, #account_dropdown, #global_actions .user_avatar')) return 'member';
        const info = document.querySelector('[data-userinfo]');
        if (info) {
            try {
                const user = JSON.parse(info.getAttribute('data-userinfo'));
                if (user.logged_in === true) return 'member';
                if (user.logged_in === false) return 'guest';
            } catch (_) { /* Fall back to the global header. */ }
        }
        const links = document.querySelectorAll('#global_actions a[href]');
        for (const link of links) {
            try {
                const url = new URL(link.href, location.href);
                if (url.origin === location.origin && /^\/login(?:\/|$)/.test(url.pathname)) return 'guest';
            } catch (_) { /* Ignore malformed links. */ }
        }
        return 'unknown';
    }

    function regionURL(force) {
        // Preserve the original spelling/order of unrelated parameters and the hash.
        const raw = location.href;
        const hashAt = raw.indexOf('#');
        const base = hashAt < 0 ? raw : raw.slice(0, hashAt);
        const hash = hashAt < 0 ? '' : raw.slice(hashAt);
        const queryAt = base.indexOf('?');
        const parts = queryAt < 0 ? [] : base.slice(queryAt + 1).split('&');
        const isCC = part => decodeURIComponent(part.split('=')[0].replace(/\+/g, ' ')).toLowerCase() === 'cc';
        if (!force && parts.some(isCC)) return null;
        const kept = force ? parts.filter(part => !isCC(part)) : parts;
        const prefix = queryAt < 0 ? base : base.slice(0, queryAt);
        const query = kept.join('&');
        return prefix + '?' + query + (query && !query.endsWith('&') ? '&' : '') + 'cc=' + region + hash;
    }

    function navigate(force = false) {
        if (region === 'off' || loginState() !== 'guest') return;
        try {
            const target = regionURL(force);
            if (!target || target === location.href) return;
            // If Steam strips cc, avoid repeatedly reloading the same destination.
            // Without session storage, skip automatic navigation conservatively.
            if (!force) {
                const previous = JSON.parse(sessionStorage.getItem(LOOP_KEY) || 'null');
                if (previous && previous.url === target && Date.now() - previous.time < 15000) return;
                sessionStorage.setItem(LOOP_KEY, JSON.stringify({ url: target, time: Date.now() }));
            }
            location.replace(target);
        } catch (_) { /* Malformed URLs or unavailable storage: leave the page alone. */ }
    }

    function mount() {
        if (!document.body || document.getElementById('cycledm-steam-store-region')) return;
        const host = document.createElement('div');
        host.id = 'cycledm-steam-store-region';
        const shadow = host.attachShadow({ mode: 'open' });
        const style = document.createElement('style');
        style.textContent = STYLES;
        const panel = document.createElement('nav');
        panel.className = 'fixed bottom-4 right-4 z-[2147483647] flex max-w-[calc(100vw-2rem)] flex-wrap items-center gap-1 rounded-xl border border-solid border-slate-600 bg-slate-900 p-2 font-sans text-sm leading-5 text-slate-100 shadow-lg';
        panel.setAttribute('aria-label', chinese ? 'Steam 商店区域' : 'Steam store region');
        let collapsed = false;
        try { collapsed = GM_getValue(COLLAPSED_SETTING, false) === true; }
        catch (_) { /* Start expanded if the saved state cannot be read. */ }
        const collapsible = document.createElement('div');
        collapsible.id = 'region-controls';
        collapsible.className = 'grid min-w-0 grid-cols-[1fr] opacity-100 transition-[grid-template-columns,opacity] duration-200 ease-in-out data-[collapsed=true]:grid-cols-[0fr] data-[collapsed=true]:opacity-0 motion-reduce:transition-none';
        const clip = document.createElement('div');
        clip.className = 'min-w-0 overflow-hidden';
        const controls = document.createElement('div');
        controls.className = 'flex w-max max-w-[calc(100vw-6rem)] flex-wrap items-center gap-1 p-1';
        clip.append(controls);
        collapsible.append(clip);
        const toggle = document.createElement('button');
        toggle.type = 'button';
        toggle.className = 'm-0 cursor-pointer rounded-lg border-0 border-solid bg-slate-700 px-3 py-2 font-sans text-sm leading-5 text-white hover:bg-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sky-300';
        toggle.setAttribute('aria-controls', collapsible.id);
        function renderCollapsed() {
            collapsible.setAttribute('data-collapsed', String(collapsed));
            collapsible.setAttribute('aria-hidden', String(collapsed));
            collapsible.inert = collapsed;
            toggle.setAttribute('aria-expanded', String(!collapsed));
            toggle.textContent = collapsed
                ? OPTIONS.find(([value]) => value === region)[1].split(' ')[0] : '›';
            toggle.title = collapsed ? (chinese ? '展开区域工具栏' : 'Expand region toolbar')
                : (chinese ? '折叠区域工具栏' : 'Collapse region toolbar');
            toggle.setAttribute('aria-label', toggle.title);
        }
        renderCollapsed();
        const status = document.createElement('span');
        status.className = 'px-2 text-xs text-slate-300';
        status.setAttribute('role', 'status');
        const buttons = [];
        function refresh() {
            const state = loginState();
            status.textContent = state === 'member' ? (chinese ? '已登录 · 暂停' : 'Signed in · paused')
                : state === 'unknown' ? (chinese ? '登录状态未知 · 暂停' : 'Unknown login · paused')
                    : (chinese ? '商店区域' : 'Store region');
            for (const [button, value] of buttons) {
                button.setAttribute('aria-pressed', String(value === region));
                button.disabled = value !== 'off' && state !== 'guest';
            }
        }
        controls.append(status);
        for (const [value, zh, en] of OPTIONS) {
            const button = document.createElement('button');
            button.type = 'button';
            button.textContent = chinese ? zh : en;
            button.className = 'm-0 cursor-pointer rounded-lg border-0 border-solid bg-slate-700 px-3 py-2 font-sans text-sm font-medium leading-5 text-white hover:bg-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sky-300 disabled:cursor-default disabled:opacity-50 aria-pressed:bg-sky-700';
            button.title = value === 'off'
                ? (chinese ? '停止后续改写，保留当前网址' : 'Stop future rewrites; keep the current URL')
                : (chinese ? '保存区域并重新加载当前页面' : 'Save region and reload this page');
            button.addEventListener('click', () => {
                if (value !== 'off' && loginState() !== 'guest') { refresh(); return; }
                try { GM_setValue(SETTING, value); }
                catch (_) {
                    status.textContent = chinese ? '无法保存设置' : 'Could not save preference';
                    return;
                }
                region = value;
                renderCollapsed();
                refresh();
                navigate(true);
            });
            buttons.push([button, value]);
            controls.append(button);
        }
        toggle.addEventListener('click', () => {
            try { GM_setValue(COLLAPSED_SETTING, !collapsed); }
            catch (_) {
                toggle.title = chinese ? '无法保存折叠状态' : 'Could not save collapsed state';
                toggle.setAttribute('aria-label', toggle.title);
                return;
            }
            collapsed = !collapsed;
            renderCollapsed();
        });
        panel.append(collapsible, toggle);
        refresh();
        shadow.append(style, panel);
        document.body.append(host);
        window.addEventListener('pageshow', () => { refresh(); navigate(); });
        document.addEventListener('visibilitychange', () => {
            if (document.visibilityState === 'visible') refresh();
        });
    }

    mount();
    navigate();
})();
